-- 602_dashboard_metric_catalog_seed.sql
--
-- Seeds dashboard_metric_catalog and dashboard_role_metric_config, both of which
-- are empty in production. While they are empty, /api/dashboards/:code/metrics
-- returns [] and every tile reports status 'unknown' with no target.
--
-- GENERATED by scripts/generate-dashboard-metric-catalog.ts from the METRICS and
-- DASHBOARD_METRICS constants. Re-run the generator instead of editing by hand.
--
-- Idempotent: ON DUPLICATE KEY UPDATE against the existing unique keys
-- (uq_metric_code, uq_role_dash_metric). Re-running refreshes metadata and
-- inserts nothing twice.
--
-- Sets no targets. A target is a business commitment, not a derivable value;
-- targets are entered through POST /api/dashboards/targets.

START TRANSACTION;

-- 19 metrics
ON DUPLICATE KEY UPDATE
  metric_name      = VALUES(metric_name),
  module_code      = VALUES(module_code),
  data_source      = VALUES(data_source),
  unit             = VALUES(unit),
  higher_is_better = VALUES(higher_is_better),
  is_active        = VALUES(is_active);

-- 401 role/dashboard/metric rows
ON DUPLICATE KEY UPDATE
  display_order = VALUES(display_order),
  is_primary    = VALUES(is_primary),
  scope_level   = VALUES(scope_level),
  is_active     = VALUES(is_active);

COMMIT;

-- Rollback:
--   DELETE FROM dashboard_role_metric_config;
--   DELETE FROM dashboard_metric_catalog;
-- Both tables were empty before this seed, so a full delete restores the prior state.
